def merge_quota(base, patch):
    """深度合并部门额度：patch 标量覆盖 base，嵌套 dict 递归合并。返回新 dict。"""
    result = dict(base)
    for k, v in patch.items():
        result[k] = v
    return result

verification_tests:
from target import merge_quota

def test_top_scalar():
    assert merge_quota({"cap": 100}, {"cap": 200}) == {"cap": 200}

def test_nested_keeps_sibling():
    r = merge_quota({"dev": {"cpu": 4, "mem": 8}}, {"dev": {"mem": 16}})
    assert r == {"dev": {"cpu": 4, "mem": 16}}

def test_mixed():
    r = merge_quota({"a": {"x": 1}, "b": 2}, {"a": {"y": 2}, "b": 3})
    assert r == {"a": {"x": 1, "y": 2}, "b": 3}
